Quick check: standard wall bike hook = wall plate + cantilevered hook that cradles the wheel rim, held by gravity. Assuming 15 kg bike, 90 mm reach, printed in PETG: a 20 mm rod keeps bending stress ~17 MPa vs ~50 MPa PETG yield — solid margin (FDM anisotropy considered). Screws into a stud, not just drywall anchors.

```openscad
// Wall-mounted bike hook (single wheel, gravity-cradle style)
// Assumes: ~15 kg bike load, printed solid/high-infill PETG or nylon,
// mounted with 2x screws into a wall stud.

$fn = 64;

// ---- parameters ----
rod_d        = 20;   // hook rod diameter (mm) - sized for bending load
plate_w      = 90;   // wall plate width
plate_h      = 60;   // wall plate height
plate_t      = 10;   // wall plate thickness
hole_d       = 5;    // screw shank clearance (M5)
head_d       = 10;   // screw head / countersink diameter
hole_spacing = 40;   // vertical spacing between the two screws
hook_reach   = 90;   // horizontal distance hook extends from wall
arc_r        = 45;   // radius of the curved (cradle) section
arc_start    = -90;  // deg, tangent matches straight rod (horizontal)
arc_end      = 120;  // deg, wraps up and over to retain the wheel
arc_steps    = 24;

// ---- wall plate with countersunk screw holes ----
module mount_plate() {
    difference() {
        translate([-plate_w/2, 0, -plate_h/2])
            cube([plate_w, plate_t, plate_h]);
        for (z = [-hole_spacing/2, hole_spacing/2])
            translate([0, 0, z]) {
                rotate([-90, 0, 0])
                    cylinder(d = hole_d, h = plate_t + 2);
                rotate([-90, 0, 0])
                    cylinder(d1 = head_d, d2 = hole_d, h = plate_t * 0.5);
            }
    }
}

// ---- hook: straight stand-off + curved cradle, built from hulled spheres ----
module hook() {
    // straight section from plate face to start of arc
    hull() {
        translate([0, plate_t, 0]) sphere(d = rod_d);
        translate([0, plate_t + hook_reach, 0]) sphere(d = rod_d);
    }

    // curved cradle section
    center = [0, plate_t + hook_reach, arc_r];
    for (i = [0 : arc_steps - 1]) {
        a0 = arc_start + (arc_end - arc_start) * i / arc_steps;
        a1 = arc_start + (arc_end - arc_start) * (i + 1) / arc_steps;
        p0 = center + [0, arc_r * cos(a0), arc_r * sin(a0)];
        p1 = center + [0, arc_r * cos(a1), arc_r * sin(a1)];
        hull() {
            translate(p0) sphere(d = rod_d);
            translate(p1) sphere(d = rod_d);
        }
    }
}

union() {
    mount_plate();
    hook();
}
```

Tune `hook_reach`/`arc_r` to your wheel size, and `rod_d` up if printing hollow/low-infill.

```scad
// Wall-mounted bike hook
// Parameters (mm)
hook_diam        = 25;   // tube diameter the hook cradles
wall_thickness   = 6;    // thickness of hook material
hook_length      = 90;   // length of horizontal arm from wall
hook_angle       = 200;  // degrees of curl to keep bike from sliding off
base_width       = 50;
base_height      = 70;
base_depth       = 10;
screw_hole_diam  = 5;
screw_inset      = 10;

$fn = 60;

module mounting_plate() {
    difference() {
        cube([base_width, base_depth, base_height], center = true);
        // screw holes, top and bottom
        for (z = [-(base_height/2 - screw_inset), (base_height/2 - screw_inset)])
            translate([0, 0, z])
                rotate([90, 0, 0])
                    cylinder(d = screw_hole_diam, h = base_depth * 2, center = true);
    }
}

module hook_arm() {
    outer_r = hook_diam/2 + wall_thickness;
    inner_r = hook_diam/2;

    translate([0, -base_depth/2, base_height/2 - outer_r])
    rotate([90, 0, 0]) {
        // straight arm out from wall
        rotate_extrude(angle = 0) circle(r = outer_r); // no-op placeholder removed below
        translate([0, hook_length, 0])
            union() {
                // straight horizontal section
                translate([0, -hook_length/2, 0])
                    cube([outer_r*2, hook_length, outer_r*2], center = true);
            }
    }
}

// Simpler, reliable construction using hull + rotate_extrude for the curl
module hook() {
    outer_r = hook_diam/2 + wall_thickness;

    // Straight arm from wall
    translate([-outer_r, -base_depth/2 - hook_length, base_height/2 - outer_r])
        rotate([-90, 0, 0])
            difference() {
                cylinder(r = outer_r, h = hook_length);
                translate([0, 0, -1])
                    cylinder(r = hook_diam/2, h = hook_length + 2);
            }
    // Support: fill the straight section so it's a solid rounded bar, then curl at the end
    translate([0, -base_depth/2 - hook_length, base_height/2])
        rotate([0, 90, 0])
            rotate_extrude(angle = hook_angle, $fn = 100)
                translate([outer_r - wall_thickness/2, 0])
                    circle(d = wall_thickness);
}

module bike_hook() {
    union() {
        mounting_plate();
        hook();
    }
}

bike_hook();
```

Note: the geometry logic for the curled hook end is the trickiest part to get perfect without iterating in the actual OpenSCAD viewer — render it and check the curl radius/position visually, and nudge `hook_length`/`outer_r` offsets if the curl doesn't line up with the straight arm.
